import{BrowserProxy}from"./browser_proxy.js";function initialize(){const script=document.createElement("script");script.type="text/javascript";script.src="https://www.gstatic.com/feedback/js/help/prod/service/lazy.min.js";script.onload=async function(){const{apiKey:apiKey}=await BrowserProxy.getInstance().handler.getApiKey();requestSurvey(apiKey)};document.head.appendChild(script)}function requestSurvey(apiKey){window.innerWidth=800;window.innerHeight=600;const helpApi=window.help.service.Lazy.create(0,{apiKey:apiKey,locale:"en-US"});let loadedSent=false;const surveyListener={surveyClosed:function(){history.pushState("","","#close")},surveyPositioning:function(_,size,animationSpec){if(!loadedSent){setTimeout((function(){history.pushState("","","#loaded")}),animationSpec.duration*1e3);loadedSent=true}const wrapper=document.querySelector("#surveyWrapper");wrapper.style.width=`${size.width}px`;wrapper.style.height=`${size.height}px`;return{anchor:3,verticalMargin:.1,horizontalMargin:.1}}};const params=new URLSearchParams(window.location.search);helpApi.requestSurvey({triggerId:params.get("trigger_id"),enableTestingMode:!!params.get("enable_testing"),preferredSurveyLanguageList:JSON.parse(decodeURIComponent(params.get("languages"))),callback:requestSurveyCallbackParam=>{if(!requestSurveyCallbackParam.surveyData){history.pushState("","","#close");return}helpApi.presentSurvey({surveyData:requestSurveyCallbackParam.surveyData,colorScheme:window.matchMedia("(prefers-color-scheme: dark)").matches?2:1,customZIndex:1e4,customLogoUrl:"https://www.gstatic.com/images"+"/branding/product/2x/chrome_48dp.png",listener:surveyListener,productData:{customData:JSON.parse(decodeURIComponent(params.get("product_specific_data")))}})}})}window.initializeHats=initialize;